import re
import requests

BASE = 'https://api.worldbank.org/v2'


def _get(url, params):
    try:
        r = requests.get(url, params=params, timeout=20)
    except requests.RequestException as e:
        raise ValueError(f'World Bank request failed: {e}')
    if r.status_code != 200:
        raise ValueError(f'World Bank API returned HTTP {r.status_code}')
    try:
        return r.json()
    except ValueError:
        raise ValueError('World Bank API returned non-JSON response')


def _resolve_country(country):
    c = country.strip()
    data = _get(f'{BASE}/country', {'format': 'json', 'per_page': 400})
    if not isinstance(data, list) or len(data) < 2 or not data[1]:
        raise ValueError('Could not load World Bank country list')
    rows = data[1]
    up = c.upper()
    if re.fullmatch(r'[A-Za-z]{2,3}', c):
        for row in rows:
            if up in (row['id'].upper(), row['iso2Code'].upper()):
                return row['id'], row['name']
    low = c.lower()
    for row in rows:
        if row['name'].lower() == low:
            return row['id'], row['name']
    matches = [row for row in rows if low in row['name'].lower()]
    if len(matches) == 1:
        return matches[0]['id'], matches[0]['name']
    raise ValueError(f'Could not resolve country: {country!r}')


def run(inp):
    if not isinstance(inp, dict):
        raise ValueError('input must be an object')
    country = inp.get('country')
    if not isinstance(country, str) or not country.strip():
        raise ValueError('country is required and must be a non-empty string')
    indicator = inp.get('indicator') or 'SP.POP.TOTL'
    if not isinstance(indicator, str) or not re.fullmatch(r'[A-Za-z0-9_.\-]+', indicator.strip()):
        raise ValueError('indicator must be a valid World Bank indicator code')
    indicator = indicator.strip()
    code, name = _resolve_country(country)
    data = _get(f'{BASE}/country/{code}/indicator/{indicator}', {'format': 'json', 'mrnev': 1})
    if not isinstance(data, list) or len(data) < 2 or not data[1]:
        msg = ''
        if isinstance(data, list) and data and isinstance(data[0], dict) and 'message' in data[0]:
            msg = data[0]['message'][0].get('value', '')
        raise ValueError(f'No data for indicator {indicator!r} and country {code}. {msg}'.strip())
    row = data[1][0]
    if row.get('value') is None:
        raise ValueError(f'No available value for {indicator!r} in {code}')
    return {
        'country': code,
        'country_name': row.get('country', {}).get('value') or name,
        'indicator': row.get('indicator', {}).get('id', indicator),
        'value': row['value'],
        'year': str(row.get('date')),
    }

